type VersionNav = {
  readonly render: (id: SuggestionId, version: VersionView) => HTMLElement
}

const createVersionNav = (view: EditorView): VersionNav => {
  let target: { readonly id: SuggestionId; readonly index: number } | null =
    null
  const stepButton = (
    label: string,
    glyph: string,
    key: string,
    offset: number,
  ) =>
    el(
      'button',
      {
        class: 'cm-ai-button cm-ai-version-step',
        attrs: {
          type: 'button',
          'aria-label': label,
          'aria-keyshortcuts': `Control+${key}`,
          title: `${label} (${formatCtrlShortcut(key, detectApplePlatform())})`,
        },
        on: {
          click: () => {
            if (target === null) return
            view.dispatch({
              effects: showVersionEffect.of({
                id: target.id,
                index: target.index + offset,
              }),
            })
          },
        },
      },
      [glyph],
    )
  const previous = stepButton('Previous version', '‹', 'H', -1)
  const next = stepButton('Next version', '›', 'L', 1)
  const count = el('span', {
    class: 'cm-ai-version-count',
    attrs: { 'aria-live': 'polite' },
  })
  const instruction = el('span', { class: 'cm-ai-version-instruction' })
  const dom = el(
    'div',
    {
      class: 'cm-ai-version',
      attrs: { role: 'group', 'aria-label': 'Versions' },
    },
    [previous, count, next, instruction],
  )
  return {
    render: (id, version) => {
      target = { id, index: version.index }
      const focused = dom.ownerDocument.activeElement
      previous.disabled = version.locked || version.index === 0
      next.disabled = version.locked || version.index === version.count - 1
      count.textContent = `${version.index + 1} / ${version.count}`
      instruction.textContent = version.instruction
      instruction.title = version.instruction
      const stuck = [previous, next].find(
        (button) => button === focused && button.disabled,
      )
      const other = stuck === previous ? next : previous
      if (stuck !== undefined && !other.disabled) other.focus()
      return dom
    },
  }
}

const refineButton = (
  view: EditorView,
  { suggestion, refineOpen }: CardContent,
) =>
  suggestion.refine.status === 'working'
    ? actionButton(view, 'Refining…', undefined, () => undefined, {
        disabled: true,
        busy: true,
      })
    : actionButton(
        view,
        'Refine',
        shortcutLabel('K'),
        () =>
          view.dispatch({
            effects: refineOpen
              ? closeRefineEffect.of(null)
              : openRefineEffect.of(suggestion.id),
          }),
        { refocus: refineOpen, expanded: refineOpen },
      )

const refineError = (
  view: EditorView,
  { refine, id }: ReadySuggestion,
  withRetry: boolean,
) =>
  refine.status === 'failed'
    ? [
        el('div', { class: 'cm-ai-card-error', attrs: { role: 'alert' } }, [
          el('span', { class: 'cm-ai-error-message' }, [
            describeError(refine.error),
          ]),
          ...(withRetry
            ? [
                actionButton(view, 'Retry', undefined, () =>
                  view.state
                    .facet(suggestionActionsFacet)
                    ?.retryRefine(view, id),
                ),
              ]
            : []),
        ]),
      ]
    : []

const renderCard = (
  view: EditorView,
  content: CardContent,
  { form }: RefineForm,
  versionNav: VersionNav,
): Node[] => {
  const { suggestion, showRationale, showActions, refineOpen, version } =
    content
  return [
    ...(version === null ? [] : [versionNav.render(suggestion.id, version)]),
    ...(showRationale
      ? [el('p', { class: 'cm-ai-rationale' }, [suggestion.rationale])]
      : []),
    ...(showActions
      ? [
          el('div', { class: 'cm-ai-card-actions' }, [
            actionButton(view, 'Accept', shortcutLabel('↵'), () =>
              acceptSuggestionById(view, suggestion.id),
            ),
            actionButton(view, 'Reject', 'Esc', () =>
              rejectSuggestionById(view, suggestion.id),
            ),
            refineButton(view, content),
          ]),
          ...(refineOpen ? [form] : []),
        ]
      : []),
    ...refineError(view, suggestion, showActions),
  ]
}

const openedRefine = (update: ViewUpdate): boolean =>
  update.transactions.some((transaction) =>
    transaction.effects.some((effect) => effect.is(openRefineEffect)),
  )

export const failRefineEffect = StateEffect.define<{
  readonly id: SuggestionId
  readonly error: ClientError
}>()
export const retryRefineEffect = StateEffect.define<SuggestionId>()
export const cancelRefineEffect = StateEffect.define<SuggestionId>()
export const showVersionEffect = StateEffect.define<{
  readonly id: SuggestionId
  readonly index: number
}>()
export const rejectEffect = StateEffect.define<SuggestionId>()
export const acceptEffect = StateEffect.define<SuggestionId>()
export const acceptManyEffect = StateEffect.define<readonly SuggestionId[]>()
export const rejectReviewEffect = StateEffect.define<null>()

const applyEffect = (
  state: SuggestionsState,
  effect: StateEffect<unknown>,
): SuggestionsState => {
  if (effect.is(beginEffect)) return beginSuggestion(state, effect.value)
  if (effect.is(resolveEffect))
    return resolveSuggestion(state, effect.value.id, effect.value.result)
  if (effect.is(failEffect))
    return failSuggestion(state, effect.value.id, effect.value.error)
  if (effect.is(retryEffect)) return retrySuggestion(state, effect.value)
  if (effect.is(beginRefineEffect))
    return beginRefine(state, effect.value.id, effect.value.instruction)
  if (effect.is(resolveRefineEffect))
    return resolveRefine(state, effect.value.id, effect.value.result)
  if (effect.is(failRefineEffect))
    return failRefine(state, effect.value.id, effect.value.error)
  if (effect.is(retryRefineEffect)) return retryRefine(state, effect.value)
  if (effect.is(cancelRefineEffect)) return cancelRefine(state, effect.value)
  if (effect.is(showVersionEffect))
    return showVersion(state, effect.value.id, effect.value.index)
  if (effect.is(rejectEffect)) return rejectSuggestion(state, effect.value)
  if (effect.is(rejectReviewEffect)) return rejectReviewSuggestions(state)
  return state
}

export const suggestionsField = StateField.define<SuggestionsState>({
  create: () => emptySuggestions,
  update: (value, transaction) => {
    const acceptedIds = transaction.effects.flatMap((effect) =>
      effect.is(acceptEffect)
        ? [effect.value]
        : effect.is(acceptManyEffect)
          ? effect.value
          : [],
    )
    const mapped =
      acceptedIds.length > 0
        ? acceptSuggestions(value, acceptedIds, transaction.changes)
        : mapSuggestions(value, transaction.changes)
    return transaction.effects.reduce(applyEffect, mapped)
  },
})

export const suggestionsOf = (state: EditorState): SuggestionsState =>
  state.field(suggestionsField)

export const cursorOf = (state: EditorState): number =>
  state.selection.main.head

export const activeOf = (state: EditorState): ReadySuggestion | undefined =>
  activeSuggestion(suggestionsOf(state), cursorOf(state))

export const activeAtCursor = (
  state: EditorState,
): ReadySuggestion | undefined => {
  const active = activeOf(state)
  const { head } = state.selection.main
  return active !== undefined && active.from <= head && head <= active.to
    ? active
    : undefined
}

export const suggestionAtCursor = (
  state: EditorState,
): Suggestion | undefined => suggestionAt(suggestionsOf(state), cursorOf(state))
